WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, LOWER(merchant) AS merchant_lower, CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END AS is_debit FROM transactions WHERE merchant IS DISTINCT FROM 'Grab'), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, PERCENTILE_APPROX(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, SIZE(COLLECT_SET(merchant)) AS num_merchants FROM sessions_transactions GROUP BY is_new_burst_tier ORDER BY is_new_burst_tier ASC NULLS FIRST;
